INSERT INTO exercises (name, muscle_group, primary_muscle, secondary_muscles, equipment, instructions) VALUES
('Supino reto', 'CHEST', 'Peitoral maior', 'Tríceps, deltoide anterior', 'Barra e banco', 'Deite no banco, desça a barra até o peito de forma controlada e empurre até estender os braços.'),
('Supino inclinado com halteres', 'CHEST', 'Peitoral superior', 'Tríceps, deltoide anterior', 'Halteres e banco inclinado', 'Com o banco inclinado, desça os halteres até a linha do peito e empurre para cima.'),
('Puxada frontal', 'BACK', 'Latíssimo do dorso', 'Bíceps, romboides', 'Polia alta', 'Puxe a barra até a altura do queixo, levando os cotovelos para baixo e para trás.'),
('Remada curvada', 'BACK', 'Dorsais', 'Bíceps, trapézio', 'Barra', 'Com o tronco inclinado e a coluna neutra, puxe a barra em direção ao abdômen.'),
('Agachamento livre', 'LEGS', 'Quadríceps', 'Glúteos, posteriores de coxa', 'Barra', 'Com a barra apoiada nas costas, desça até as coxas ficarem paralelas ao chão e suba empurrando o chão.'),
('Leg press', 'LEGS', 'Quadríceps', 'Glúteos', 'Máquina leg press', 'Empurre a plataforma sem travar os joelhos no final e desça de forma controlada.'),
('Desenvolvimento com halteres', 'SHOULDERS', 'Deltoides', 'Tríceps', 'Halteres', 'Sentado, empurre os halteres acima da cabeça e retorne até a altura das orelhas.'),
('Elevação lateral', 'SHOULDERS', 'Deltoide lateral', 'Trapézio', 'Halteres', 'Eleve os braços lateralmente até a altura dos ombros, com os cotovelos levemente flexionados.'),
('Rosca direta', 'BICEPS', 'Bíceps braquial', 'Antebraço', 'Barra', 'Em pé, flexione os cotovelos levando a barra até o peito, sem balançar o tronco.'),
('Tríceps pulley', 'TRICEPS', 'Tríceps braquial', 'Antebraço', 'Polia alta', 'Com os cotovelos junto ao corpo, estenda os braços para baixo e retorne de forma controlada.'),
('Abdominal crunch', 'ABS', 'Reto abdominal', 'Oblíquos', 'Peso corporal', 'Deitado, eleve os ombros do chão contraindo o abdômen, sem puxar o pescoço.'),
('Elevação pélvica', 'GLUTES', 'Glúteo máximo', 'Posteriores de coxa', 'Barra e banco', 'Com as costas apoiadas no banco, eleve o quadril até alinhar tronco e coxas e contraia os glúteos.'),
('Panturrilha em pé', 'CALVES', 'Gastrocnêmio', 'Sóleo', 'Máquina de panturrilha', 'Eleve os calcanhares o máximo possível, pause no topo e desça alongando bem.');